const gui_bitmap_t *gui_asset_get(gui_icon_id_t icon, unsigned size)
{
    for (size_t i = 0; i < sizeof variants / sizeof variants[0]; ++i) {
        if (variants[i].id == icon && variants[i].size == size) return &variants[i].bitmap;
    }
    return NULL;
}

size_t gui_assets_bytes(void)
{
    return sizeof art_rgb + sizeof art_alpha + sizeof variants;
}

_Static_assert(sizeof art_rgb + sizeof art_alpha + sizeof variants <= 49152, "GUI art budget exceeded");
